import{_ as t,o,c as a,a6 as r}from"./chunks/framework.BBdhcoHf.js";const g=JSON.parse('{"title":"ADR-008: Enforce Channel Subject Validation at the Protocol Layer","description":"","frontmatter":{},"headers":[],"relativePath":"adr/008-subject-namespace-validation.md","filePath":"adr/008-subject-namespace-validation.md","lastUpdated":1771970963000}'),n={name:"adr/008-subject-namespace-validation.md"};function c(i,e,d,s,l,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /adr/008-subject-namespace-validation.md for this page in Markdown format</div><h1 id="adr-008-enforce-channel-subject-validation-at-the-protocol-layer" tabindex="-1">ADR-008: Enforce Channel Subject Validation at the Protocol Layer <a class="header-anchor" href="#adr-008-enforce-channel-subject-validation-at-the-protocol-layer" aria-label="Permalink to “ADR-008: Enforce Channel Subject Validation at the Protocol Layer”">​</a></h1><ul><li><strong>Date</strong>: 2025-11-23</li><li><strong>Status</strong>: Accepted</li><li><strong>Applies to</strong>: SBP</li><li><strong>Tags</strong>: protocol, validation, correctness, conformance</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>ADR-006 mandates that all <code>MessageFrame.subject</code> values use exact-match channel subjects (<code>rpc</code>, <code>event</code>, <code>stream</code>) or the <code>app/</code> prefix.</p><p>The protocol layer did not enforce this contract. The wire codec accepted any string; validation only existed in <code>@sideband/rpc</code> (optional). This violated ADR-006 and the principle of correctness-first design.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Move subject validation into <code>@sideband/protocol</code> — the only package owning the wire-format contract.</p><ol><li><p><strong>Add branded <code>Subject</code> type</strong>: Prevents accidental misuse at the TypeScript level.</p></li><li><p><strong>Add <code>asSubject()</code> validator</strong>: Runtime validation enforcing:</p><ul><li>1–256 UTF-8 bytes (measured correctly, not code units)</li><li>Valid channel (<code>rpc</code>, <code>event</code>, <code>stream</code> exact match, or <code>app/</code> prefix)</li><li>No null bytes or empty strings</li><li>Throws <code>ProtocolError(ProtocolViolation)</code> on violation</li></ul></li><li><p><strong>Update <code>MessageFrame.subject</code></strong>: Change from <code>string</code> to <code>Subject</code> type.</p></li><li><p><strong>Add <code>createMessageFrame()</code> factory</strong>: User-facing API that validates subject at construction.</p></li><li><p><strong>Update <code>decodeFrame()</code></strong>: Validate subject on wire decode. Invalid subjects → fatal protocol violation → connection close.</p></li><li><p><strong>Update RPC layer</strong>: Re-export protocol validator as <code>asRpcSubject()</code>. Remove duplicate validation.</p></li></ol><h2 id="technical-details" tabindex="-1">Technical Details <a class="header-anchor" href="#technical-details" aria-label="Permalink to “Technical Details”">​</a></h2><p><strong>UTF-8 byte length</strong>: Validator measures via <code>TextEncoder</code> (not JavaScript <code>.length</code>, which counts code units). Correctly handles multi-byte characters.</p><p><strong>Channel list extensibility</strong>: Stored as const arrays (<code>RESERVED_CHANNELS</code> for exact matches, <code>RESERVED_PREFIXES</code> for prefix-based), enabling future extensions (e.g., <code>signal</code>) without API breakage. Update the relevant array, release minor version.</p><p><strong>Error semantics</strong>: Invalid subjects are fatal. On send: synchronous throw. On receive: <code>ProtocolError(ProtocolViolation)</code> → <code>ErrorFrame</code> → close connection.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Impact</th></tr></thead><tbody><tr><td><strong>Correctness</strong></td><td>Every frame on the wire provably conforms to ADR-006. No bypass paths.</td></tr><tr><td><strong>API safety</strong></td><td>Invalid subjects rejected at construction time, not silently sent or received.</td></tr><tr><td><strong>Breaking change</strong></td><td>Pre-1.0 acceptable. Raw <code>MessageFrame</code> construction will fail type-check or throw.</td></tr><tr><td><strong>Performance</strong></td><td>Negligible: one <code>TextEncoder</code> + prefix check per message.</td></tr></tbody></table><h2 id="alternatives-considered-and-rejected" tabindex="-1">Alternatives Considered and Rejected <a class="header-anchor" href="#alternatives-considered-and-rejected" aria-label="Permalink to “Alternatives Considered and Rejected”">​</a></h2><ul><li><strong>Validate only in RPC</strong>: Higher layers bypass; transports/tools emit invalid frames.</li><li><strong>Validate only on send</strong>: Malicious peers can flood with invalid subjects (DoS).</li><li><strong>Validate only on decode</strong>: Invalid frames constructed internally; bugs in middlewares.</li><li><strong>Configurable prefix set</strong>: Foot-gun; violates &quot;one obvious way&quot; principle.</li></ul>',17)])])}const u=t(n,[["render",c]]);export{g as __pageData,u as default};
